    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for el, x in s.get('composition', {}).items():
        z = props.get(el, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and math.isfinite(z) and z >= 0:
            total += x * z
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, t.get('occupancy', 1.0)) if t.get('occupancy', 1.0) is not None else 0.0 for t in sites]
    edges = [e for e in s.get('neighbors', ()) if e.get('distance_A') is not None and 0 < e['distance_A'] <= 6.0 and 0 <= e['i'] < n and 0 <= e['j'] < n]
    nearest = [math.inf for i in range(n)]
    for e in edges:
        if occ[e['j']] > 0:
            nearest[e['i']] = min(nearest[e['i']], e['distance_A'])
    coord = [0.0 for i in range(n)]
    for e in edges:
        if e['distance_A'] <= 1.25 * nearest[e['i']]:
            coord[e['i']] += occ[e['j']]
    weight = sum(occ)
    return float(sum(occ[i] * coord[i] for i in range(n)) / weight) if weight > 0 else 0.0

