    occ = [max(0.0, t.get('occupancy', 1.0)) if t.get('occupancy', 1.0) is not None else 0.0 for t in sites]
    edges = [e for e in s.get('neighbors', ()) if e.get('distance_A') is not None and 0 < e['distance_A'] <= 6.0 and 0 <= e['i'] < n and 0 <= e['j'] < n]
    nearest = [math.inf for i in range(n)]
    for e in edges:
        if occ[e['j']] > 0:
            nearest[e['i']] = min(nearest[e['i']], e['distance_A'])
    coord = [0.0 for i in range(n)]
    for e in edges:
        if e['distance_A'] <= 1.25 * nearest[e['i']]:
            coord[e['i']] += occ[e['j']]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * coord[i] for i in range(n)) / weight
    var = sum(occ[i] * (coord[i] - mean) ** 2 for i in range(n)) / weight
    return float(math.sqrt(max(0.0, var)) / mean) if mean > 0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, t.get('occupancy', 1.0)) if t.get('occupancy', 1.0) is not None else 0.0 for t in sites]
    counts = {}
    for i in range(n):
        el = sites[i].get('element')
        counts[el] = counts.get(el, 0.0) + occ[i]
    atom_weight = sum(occ)
    if atom_weight <= 0:
        return 0.0
    expected = sum((x / atom_weight) ** 2 for x in counts.values())
    edges = [e for e in s.get('neighbors', ()) if e.get('distance_A') is not None and 0 < e['distance_A'] <= 6.0 and 0 <= e['i'] < n and 0 <= e['j'] < n]
    nearest = [math.inf for i in range(n)]
    for e in edges:
        if occ[e['j']] > 0:
            nearest[e['i']] = min(nearest[e['i']], e['distance_A'])
    same = 0.0
    weight = 0.0
    for e in edges:
        i = e['i']
        j = e['j']
        if e['distance_A'] <= 1.25 * nearest[i]:
            w = occ[i] * occ[j]
            weight += w
            if sites[i].get('element') == sites[j].get('element'):
                same += w
    return float(same / weight - expected) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    matrix = s.get('lattice', {}).get('matrix')
    if n == 0 or matrix is None or len(matrix) != 3:
        return 0.0
    occ = [max(0.0, t.get('occupancy', 1.0)) if t.get('occupancy', 1.0) is not None else 0.0 for t in sites]
    edges = [e for e in s.get('neighbors', ()) if e.get('distance_A') is not None and 0 < e['distance_A'] <= 6.0 and 0 <= e['i'] < n and 0 <= e['j'] < n]
    nearest = [math.inf for i in range(n)]
    for e in edges:
        if occ[e['j']] > 0:
            nearest[e['i']] = min(nearest[e['i']], e['distance_A'])
    tensors = np.zeros((n, 3, 3))
    for e in edges:
        i = e['i']
        j = e['j']
        if occ[i] > 0 and occ[j] > 0 and e['distance_A'] <= 1.25 * nearest[i]:
            fi = sites[i].get('frac_coords')
            fj = sites[j].get('frac_coords')
            image = e.get('image')
            if fi is not None and fj is not None and image is not None:
                delta = [fj[k] + image[k] - fi[k] for k in range(3)]
                vector = [sum(delta[k] * matrix[k][a] for k in range(3)) for a in range(3)]
                norm2 = sum(x * x for x in vector)
                if norm2 > 0 and math.isfinite(norm2):
                    for a in range(3):
                        for b in range(3):
                            tensors[i, a, b] += occ[j] * vector[a] * vector[b] / norm2
    values = np.linalg.eigvalsh(tensors)
    total = 0.0
    weight = 0.0
    for i in range(n):
        trace = float(sum(values[i]))
        if trace > 0 and occ[i] > 0:
            total += occ[i] * max(0.0, float(values[i, 0])) / trace
            weight += occ[i]
    return float(total / weight) if weight > 0 else 0.0

