def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if n == 0 or v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    occ = [max(0.0, t.get('occupancy', 1.0)) if t.get('occupancy', 1.0) is not None else 0.0 for t in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    count = 0.0
    for e in s.get('neighbors', ()):
        i = e['i']
        j = e['j']
        d = e.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6.0:
            count += occ[i] * occ[j]
    return float(count * v / (weight * (4.0 * math.pi * 6.0 ** 3 / 3.0)))
